// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

interface IERC20 {
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

interface IPSM {
    function sellGem(address usr, uint256 gemAmt) external;
    function buyGem(address usr, uint256 gemAmt) external;
    function tin() external view returns (uint256);
    function tout() external view returns (uint256);
}

interface IJoin {
    function join(address usr, uint256 wad) external;
}

contract PSMAdapter {
    // ============================================================================
    // Constants
    // ============================================================================

    address public immutable PSM          = 0xf6e72db5454dd049d0788e411b06cfaf16853042;
    address public immutable USDC         = 0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48;
    address public immutable USDS         = 0xdc035d45d973e3ec169d2276ddab16f1e407384f;
    address public immutable VAT          = 0x35d1b3f3d7966a1dfe207aa4514c12a259a0492b;
    address public immutable USDS_JOIN    = 0x9759a6ac90977b93b58547b4a71c78317f391a28;
    address public immutable ADAPTER      = 0x3c0f895007ca717aa01c8693e59df1e8c3777feb;
    bytes32  public immutable ILK        = "LITE-PSM-USDC-A";

    uint256  public immutable PRECISION  = 1e12;  // 10^12
    uint256  public immutable RAY        = 1e27;  // Standard Maker RAY precision

    // ============================================================================
    // Functions
    // ============================================================================

    /// @notice Sell USDC for USDS through PSM
    /// @param usr User address receiving USDS
    /// @param gemAmt Amount of USDC to sell (in USDC decimals)
    /// @return Amount of USDS received
    function sellUSDC(address usr, uint256 gemAmt) external payable returns (uint256) {
        require(usr == address(uint160(usr)), "Invalid address");

        // Transfer USDC from caller to this contract
        IERC20(USDC).transferFrom(msg.sender, address(this), gemAmt);

        // Call PSM to sell gem (USDC) for dai (USDS)
        IPSM(PSM).sellGem(address(this), gemAmt);

        // Join USDS into the vault system
        uint256 usdsAmt = _getUSDSAmount(gemAmt);
        IJoin(USDS_JOIN).join(address(this), usdsAmt);

        // Transfer USDS to user via adapter
        IAdapter(ADAPTER).transferTo(usr, usdsAmt);

        return usdsAmt;
    }

    /// @notice Buy USDC with USDS through PSM
    /// @param usr User address receiving USDC
    /// @param gemAmt Amount of USDC to buy (in USDC decimals)
    /// @return Amount of USDS required
    function buyUSDC(address usr, uint256 gemAmt) external payable returns (uint256) {
        require(usr == address(uint160(usr)), "Invalid address");

        // Get PSM fee rate (tin)
        uint256 tin = IPSM(PSM).tin();

        // Validate calculation precision
        require(_safeMul(PRECISION, gemAmt) / gemAmt == PRECISION || gemAmt == 0, "Overflow");

        // Calculate USDS required: (gemAmt * PRECISION * tin / RAY) + (gemAmt * PRECISION)
        uint256 feeComponent = _safeMul(_safeMul(PRECISION, tin), gemAmt) / RAY;
        uint256 principalComponent = PRECISION * gemAmt;
        uint256 usdsRequired = feeComponent + principalComponent;

        // Validate bounds
        require(
            PRECISION * gemAmt <= usdsRequired,
            "Calculation error"
        );

        // Transfer USDS from caller to this contract
        IERC20(USDS).transferFrom(msg.sender, address(this), usdsRequired);

        // Join USDS into the vault system
        IJoin(USDS_JOIN).join(address(this), usdsRequired);

        // Prepare adapter for USDC transfer
        IAdapter(ADAPTER).prepare(usr, usdsRequired);

        // Call PSM to buy gem (USDC) with dai (USDS)
        IPSM(PSM).buyGem(usr, gemAmt);

        return usdsRequired;
    }

    /// @notice Fallback function - not payable
    receive() external payable {
        revert("No fallback accepted");
    }

    // ============================================================================
    // Internal Helpers
    // ============================================================================

    function _getUSDSAmount(uint256 gemAmt) internal view returns (uint256) {
        // Convert gem amount to USDS amount based on precision
        return gemAmt * PRECISION;
    }

    function _safeMul(uint256 a, uint256 b) internal pure returns (uint256) {
        if (a == 0 || b == 0) return 0;
        uint256 c = a * b;
        require(c / a == b, "Multiplication overflow");
        return c;
    }
}

// Interface for adapter contract
interface IAdapter {
    function transferTo(address usr, uint256 amount) external;
    function prepare(address usr, uint256 amount) external;
}
