```solidity
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

/// @title DaiJoin - Bridge between Dai token and Vat accounting system
/// @notice Allows users to join/exit the MakerDAO system by converting 
///         between internal Vat units and external Dai tokens
contract DaiJoin {
    // ========================================================================
    // STORAGE VARIABLES
    // ========================================================================

    /// @notice Authorization mapping: address => authorized (1 = authorized, 0 = not)
    mapping(address => uint256) private wards;

    /// @notice Address of the Vat contract (Maker's core accounting system)
    address public vat;

    /// @notice Address of the Dai token contract
    address public dai;

    /// @notice Live flag: 1 = contract is active, 0 = contract is disabled
    uint256 private live;

    // ========================================================================
    // EVENTS
    // ========================================================================

    /// @notice Emitted on all state-changing functions
    /// @param sig Function selector
    /// @param caller Message sender
    /// @param arg1 First argument (varies by function)
    /// @param arg2 Second argument (varies by function)
    event LogNote(
        bytes4 indexed sig,
        address indexed caller,
        bytes32 arg1,
        bytes32 arg2
    );

    // ========================================================================
    // VIEW FUNCTIONS
    // ========================================================================

    /// @notice Check if an address is authorized
    /// @param usr Address to check
    /// @return 1 if authorized, 0 otherwise
    function wards(address usr) external view returns (uint256) {
        return wards[usr];
    }

    /// @notice Get the Vat contract address
    /// @return Vat contract address
    function vat() external view returns (address) {
        return vat;
    }

    /// @notice Get the Dai token contract address
    /// @return Dai token contract address
    function dai() external view returns (address) {
        return dai;
    }

    /// @notice Check if contract is live/active
    /// @return 1 if live, 0 if disabled
    function live() external view returns (uint256) {
        return live;
    }

    // ========================================================================
    // ADMIN FUNCTIONS
    // ========================================================================

    /// @notice Grant authorization to an address
    /// @dev Only callable by authorized addresses
    /// @param usr Address to authorize
    function rely(address usr) external {
        require(msg.data.length >= 36, "DaiJoin/invalid-calldata");
        require(wards[msg.sender] == 1, "DaiJoin/not-authorized");

        wards[usr] = 1;

        emit LogNote(
            msg.sig,
            msg.sender,
            bytes32(uint256(uint160(usr))),
            bytes32(0)
        );
    }

    /// @notice Revoke authorization from an address
    /// @dev Only callable by authorized addresses
    /// @param usr Address to deauthorize
    function deny(address usr) external {
        require(msg.data.length >= 36, "DaiJoin/invalid-calldata");
        require(wards[msg.sender] == 1, "DaiJoin/not-authorized");

        wards[usr] = 0;

        emit LogNote(
            msg.sig,
            msg.sender,
            bytes32(uint256(uint160(usr))),
            bytes32(0)
        );
    }

    /// @notice Disable the contract (emergency stop)
    /// @dev Only callable by authorized addresses
    function cage() external {
        require(wards[msg.sender] == 1, "DaiJoin/not-authorized");

        live = 0;

        emit LogNote(
            msg.sig,
            msg.sender,
            bytes32(0),
            bytes32(0)
        );
    }

    // ========================================================================
    // MAIN FUNCTIONS
    // ========================================================================

    /// @notice Join the system: lock Dai tokens, receive internal Vat credit
    /// @dev Transfers Dai from caller to this contract, then credits Vat
    /// @param usr Address to credit in the Vat system
    /// @param wad Amount of Dai to join (in wei, 18 decimals)
    function join(address usr, uint256 wad) external {
        require(msg.data.length >= 68, "DaiJoin/invalid-calldata");

        if (wad == 0) {
            // Zero amount: just initialize Vat slot
            require(vat.code.length > 0, "DaiJoin/vat-not-deployed");
            (bool success, ) = vat.call(
                abi.encodeWithSignature(
                    "move(address,address,uint256)",
                    address(this),
                    usr,
                    0
                )
            );
            require(success, "DaiJoin/vat-call-failed");
        } else {
            // Validate wad doesn't overflow when scaled
            require(wad > 0, "DaiJoin/zero-amount");
            require(
                1000000000 * 1e18 * wad / wad == 1000000000 * 1e18,
                "DaiJoin/overflow"
            );

            require(vat.code.length > 0, "DaiJoin/vat-not-deployed");
            (bool success, ) = vat.call(
                abi.encodeWithSignature(
                    "move(address,address,uint256)",
                    address(this),
                    usr,
                    1000000000 * 1e18 * wad
                )
            );
            require(success, "DaiJoin/vat-call-failed");
        }

        // Transfer Dai from caller to this contract
        require(dai.code.length > 0, "DaiJoin/dai-not-deployed");
        (success, ) = dai.call(
            abi.encodeWithSignature(
                "transferFrom(address,address,uint256)",
                msg.sender,
                address(this),
                wad
